using System.Text.Json;

namespace MicroEngine.Graphics.Devices;

/// <summary>Bytecode (or MSL source) of one shader in one format, with its entry point.</summary>
/// <param name="Bytes">The code as <see cref="ShaderDescription.Code"/> takes it.</param>
/// <param name="EntryPoint">Entry point name ("main"; "main0" for MSL generated by SPIRV-Cross).</param>
public readonly record struct ShaderCode(ReadOnlyMemory<byte> Bytes, string EntryPoint);

/// <summary>
/// A shader compiled ahead of time from one HLSL source into every format a tier-1 device may accept (DXIL for
/// Direct3D 12, SPIR-V for Vulkan, MSL for Metal), with the resource counts reflection found. It is what
/// <c>microengine shaders</c> writes (one <c>.shader</c> file per HLSL file) and what a game ships: nothing compiles at
/// run time. <see cref="DescriptionFor"/> picks the format a device should be given; a device without custom shaders
/// gets the typed <see cref="GraphicsCapabilityException"/>, as for any undeclared capability.
/// </summary>
/// <remarks>
/// The file is UTF-8 JSON: <c>{"format":"microengine-shader","version":1,"stage":"vertex"|"fragment","source":...,
/// "resources":{"samplers":n,"uniformBuffers":n},"code":{"dxil"|"spirv"|"msl":{"entry":...,"base64":...}}}</c>.
/// Binding rules are SDL_GPU's (see <see cref="ShaderResources"/>).
/// </remarks>
public sealed class CompiledShader
{
    /// <summary>The file extension of a compiled shader ("sprite.frag.hlsl" compiles to "sprite.frag.shader").</summary>
    public const string FileExtension = ".shader";

    /// <summary>The file format version this assembly reads and writes.</summary>
    public const int FormatVersion = 1;

    private const string Magic = "microengine-shader";
    private static readonly (ShaderFormat Format, string Name)[] Names = [(ShaderFormat.Dxil, "dxil"), (ShaderFormat.SpirV, "spirv"), (ShaderFormat.Msl, "msl")];
    private readonly Dictionary<ShaderFormat, ShaderCode> _code;

    /// <summary>Creates a compiled shader from its code in one or more formats.</summary>
    /// <param name="stage">Stage.</param>
    /// <param name="resources">Reflected resource counts (the same for every format).</param>
    /// <param name="code">Code by format; each key is exactly one format.</param>
    /// <param name="source">The source file it was compiled from, for diagnostics.</param>
    /// <exception cref="ArgumentException">No code, a key that is not exactly one format, or an empty entry point or code.</exception>
    public CompiledShader(ShaderStage stage, ShaderResources resources, IReadOnlyDictionary<ShaderFormat, ShaderCode> code, string? source = null)
    {
        ArgumentNullException.ThrowIfNull(code);
        if (code.Count == 0) throw new ArgumentException("a compiled shader needs code in at least one format", nameof(code));
        foreach (var (format, c) in code)
        {
            if (format is not (ShaderFormat.Dxil or ShaderFormat.SpirV or ShaderFormat.Msl)) throw new ArgumentException($"{format} is not exactly one shader format", nameof(code));
            if (c.Bytes.IsEmpty || string.IsNullOrEmpty(c.EntryPoint)) throw new ArgumentException($"{format}: empty code or entry point", nameof(code));
        }
        Stage = stage;
        Resources = resources;
        Source = source;
        _code = new Dictionary<ShaderFormat, ShaderCode>(code);
    }

    /// <summary>Stage.</summary>
    public ShaderStage Stage { get; }

    /// <summary>Reflected resource counts.</summary>
    public ShaderResources Resources { get; }

    /// <summary>The source file it was compiled from, or null.</summary>
    public string? Source { get; }

    /// <summary>The formats this shader has code for.</summary>
    public ShaderFormat Formats => _code.Keys.Aggregate(ShaderFormat.None, (all, f) => all | f);

    /// <summary>The code in <paramref name="format"/>, if compiled for it.</summary>
    public bool TryGetCode(ShaderFormat format, out ShaderCode code) => _code.TryGetValue(format, out code);

    /// <summary>
    /// The description to give a device with <paramref name="capabilities"/>: the format its API runs natively
    /// (DXIL on Direct3D 12, MSL on Metal, SPIR-V on Vulkan), otherwise the first format both sides have.
    /// </summary>
    /// <exception cref="GraphicsCapabilityException">The device declares no custom shaders (<see cref="GraphicsFeatures.Shaders"/>), or none of the formats this shader was compiled for.</exception>
    public ShaderDescription DescriptionFor(GraphicsCapabilities capabilities)
    {
        ArgumentNullException.ThrowIfNull(capabilities);
        if (!capabilities.Has(GraphicsFeatures.Shaders)) throw new GraphicsCapabilityException("CreateShader", capabilities.Backend, GraphicsFeatures.Shaders);
        var preferred = capabilities.ApiName switch { "direct3d12" => ShaderFormat.Dxil, "metal" => ShaderFormat.Msl, "vulkan" => ShaderFormat.SpirV, _ => ShaderFormat.None };
        ShaderFormat chosen = preferred != ShaderFormat.None && (capabilities.ShaderFormats & preferred) != 0 && _code.ContainsKey(preferred) ? preferred
            : Names.Select(n => n.Format).FirstOrDefault(f => (capabilities.ShaderFormats & f) != 0 && _code.ContainsKey(f));
        if (chosen == ShaderFormat.None)
            throw new GraphicsCapabilityException("CreateShader", capabilities.Backend, GraphicsFeatures.None,
                $"a shader format the device accepts (device: {capabilities.ShaderFormats}; compiled: {Formats})");
        var code = _code[chosen];
        return new ShaderDescription(Stage, chosen, code.Bytes, code.EntryPoint, Resources);
    }

    /// <summary>Creates the shader on <paramref name="device"/> in the format <see cref="DescriptionFor"/> picks.</summary>
    /// <exception cref="GraphicsCapabilityException">See <see cref="DescriptionFor"/>.</exception>
    public Shader Create(IGraphicsDevice device)
    {
        ArgumentNullException.ThrowIfNull(device);
        return device.CreateShader(DescriptionFor(device.Capabilities));
    }

    /// <summary>Reads a compiled shader file.</summary>
    /// <exception cref="InvalidDataException">The data is not a compiled shader of a version this assembly reads.</exception>
    public static CompiledShader Parse(ReadOnlySpan<byte> utf8Json)
    {
        try
        {
            using var document = JsonDocument.Parse(utf8Json.ToArray());
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object || !root.TryGetProperty("format", out var magic) || magic.GetString() != Magic)
                throw new InvalidDataException("not a compiled shader (\"format\": \"microengine-shader\" is missing)");
            int version = root.GetProperty("version").GetInt32();
            if (version != FormatVersion) throw new InvalidDataException($"compiled shader version {version}; this engine reads version {FormatVersion} (recompile with this SDK's microengine shaders)");
            var stage = root.GetProperty("stage").GetString() switch
            {
                "vertex" => ShaderStage.Vertex,
                "fragment" => ShaderStage.Fragment,
                var s => throw new InvalidDataException($"unknown shader stage '{s}'"),
            };
            var r = root.GetProperty("resources");
            int Count(string name) => r.TryGetProperty(name, out var v) ? v.GetInt32() : 0;
            var resources = new ShaderResources(Count("samplers"), Count("uniformBuffers"), Count("storageTextures"), Count("storageBuffers"));
            var code = new Dictionary<ShaderFormat, ShaderCode>();
            foreach (var entry in root.GetProperty("code").EnumerateObject())
            {
                var format = Names.FirstOrDefault(n => n.Name == entry.Name).Format;
                if (format == ShaderFormat.None) throw new InvalidDataException($"unknown shader format '{entry.Name}'");
                code[format] = new ShaderCode(Convert.FromBase64String(entry.Value.GetProperty("base64").GetString()!), entry.Value.GetProperty("entry").GetString()!);
            }
            string? source = root.TryGetProperty("source", out var src) ? src.GetString() : null;
            return new CompiledShader(stage, resources, code, source);
        }
        catch (Exception e) when (e is JsonException or KeyNotFoundException or FormatException or InvalidOperationException or ArgumentException)
        {
            throw new InvalidDataException($"invalid compiled shader: {e.Message}", e);
        }
    }

    /// <summary>The file form of this shader (UTF-8 JSON, formats in a fixed order, so the same compilation gives the same bytes).</summary>
    public byte[] ToBytes()
    {
        using var stream = new MemoryStream();
        using (var w = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true }))
        {
            w.WriteStartObject();
            w.WriteString("format", Magic);
            w.WriteNumber("version", FormatVersion);
            w.WriteString("stage", Stage == ShaderStage.Vertex ? "vertex" : "fragment");
            if (Source is not null) w.WriteString("source", Source);
            w.WriteStartObject("resources");
            w.WriteNumber("samplers", Resources.Samplers);
            w.WriteNumber("uniformBuffers", Resources.UniformBuffers);
            w.WriteNumber("storageTextures", Resources.StorageTextures);
            w.WriteNumber("storageBuffers", Resources.StorageBuffers);
            w.WriteEndObject();
            w.WriteStartObject("code");
            foreach (var (format, name) in Names)
            {
                if (!_code.TryGetValue(format, out var c)) continue;
                w.WriteStartObject(name);
                w.WriteString("entry", c.EntryPoint);
                w.WriteBase64String("base64", c.Bytes.Span);
                w.WriteEndObject();
            }
            w.WriteEndObject();
            w.WriteEndObject();
        }
        stream.WriteByte((byte)'\n');
        return stream.ToArray();
    }

    /// <inheritdoc/>
    public override string ToString() => $"{Source ?? "shader"} ({Stage}, {Formats})";
}
